    private ModSounds() {
    }

    private static RegistryEntry<SoundEvent> sound(String name) {
        return Services.REGISTRAR.register(Registries.SOUND_EVENT, name,
                () -> SoundEvent.createVariableRangeEvent(SporeAndStem.id(name)));
    }

    public static void init() {
    }
